import { createIcon } from "../../../theme/iconRegistry.js";

export function SellerShowroomPanel({ summary = {} } = {}) {
  const section = document.createElement("section");
  section.id = "slr_showroom_panel_section";
  section.className = "grid min-w-0 gap-4 rounded-[1.75rem] border border-[var(--pb-card-border)] bg-[linear-gradient(135deg,rgba(255,255,255,0.92),rgba(234,244,249,0.76),rgba(250,244,237,0.70))] p-4 shadow-[0_18px_52px_rgba(15,23,42,0.08)] backdrop-blur-xl transition-shadow duration-150 sm:p-5";

  const header = document.createElement("div");
  header.className = "flex min-w-0 flex-col gap-3 sm:flex-row sm:items-start sm:justify-between";

  const left = document.createElement("div");
  left.className = "flex min-w-0 items-start gap-3";

  const icon = document.createElement("span");
  icon.className = "grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-[linear-gradient(135deg,#1e81b0,#1e81b0)] text-white shadow-[0_14px_34px_rgba(30,129,176,0.18)]";
  icon.append(createIcon("showroom", { className: "h-5 w-5" }));

  const copy = document.createElement("div");
  copy.className = "grid min-w-0 gap-1";
  copy.append(
    textNode("h2", "break-words text-lg font-black tracking-normal text-gray-950", summary.showroomName ?? "Showroom"),
  );

  left.append(icon, copy);

  header.append(left);

  const text = summary.showroomReady
    ? null
    : textNode(
      "p",
      "max-w-3xl text-xs leading-6 text-gray-600",
      "Lengkapi showroom sebelum UAT showroom agar listing dan transaksi lebih mudah diverifikasi.",
    );

  const facts = document.createElement("section");
  facts.id = "slr_showroom_facts_section";
  facts.className = "grid gap-2 sm:grid-cols-3";
  [
    ["Listing", `${summary.totalCars ?? 0} unit`],
    ["Published", `${summary.publishedCars ?? 0} aktif`],
    ["Follow up", `${summary.pendingTransactions ?? 0} transaksi`],
  ].forEach(([label, value]) => {
    const item = document.createElement("section");
    item.id = `slr_showroom_fact_${label.toLowerCase().replace(/\s+/g, "_")}_section`;
    item.className = "rounded-[1.25rem] border border-[var(--pb-card-border)] bg-white/74 p-3 shadow-sm";
    item.append(
      textNode("p", "text-[10px] font-black uppercase tracking-[0.14em] text-gray-500", label),
      textNode("p", "text-xs font-black text-gray-950", value),
    );
    facts.append(item);
  });

  section.append(header, ...(text ? [text] : []), facts);
  return section;
}

function textNode(tagName, className, text) {
  const node = document.createElement(tagName);
  node.className = className;
  node.textContent = text;
  return node;
}
